#include <filesystem>
void pilot_guard(){rlimit c,m;getrlimit(RLIMIT_CPU,&c);getrlimit(RLIMIT_AS,&m);require(c.rlim_cur==29&&c.rlim_max==29,"pilot CPU hard guard");require(m.rlim_cur==256ul*1024*1024&&m.rlim_max==m.rlim_cur,"pilot memory guard");cpu_set_t s;CPU_ZERO(&s);require(sched_getaffinity(0,sizeof(s),&s)==0&&CPU_COUNT(&s)==1&&CPU_ISSET(4,&s),"pilot CPU4 affinity");struct sigaction a;sigaction(SIGXCPU,nullptr,&a);sigset_t blocked;sigprocmask(SIG_BLOCK,nullptr,&blocked);require(a.sa_handler==SIG_DFL&&!sigismember(&blocked,SIGXCPU),"pilot SIGXCPU guard");int pd;prctl(PR_GET_PDEATHSIG,&pd);require(pd==SIGKILL,"pilot parent-death guard");std::cerr<<"GUARDS CPU=29 AS=256MiB AFFINITY=4\n";}
size_t bits(const Mat&A){size_t n=0;for(auto&z:A.a)n=std::max(n,mpz_sizeinbase(z.get_mpz_t(),2));return n;}
int main(int argc,char**argv){try{pilot_guard();require(argc==4,"arguments blocks anchors output-directory");std::ifstream anc(argv[2]);require((bool)anc,"anchor input");Z wantN,wantH;bool hn=false,hh=false;std::string line;while(std::getline(anc,line)){if(line.rfind("N0_32=",0)==0){wantN=Z(line.substr(6));hn=true;}if(line.rfind("H0_32=",0)==0){wantH=Z(line.substr(6));hh=true;}}require(hn&&hh&&wantN>0,"accepted anchor keys");std::ifstream in(argv[1]);int nb;in>>nb;require((bool)in&&nb==11,"local block header");Z N,H,B2;int sizes[11]={1,8,32,80,136,130,136,80,32,8,1};for(int k=0;k<nb;k++){int q,d;in>>q>>d;require(q==-10+2*k&&d==sizes[k],"ordered block identity");Mat T(d),O(d),U(d),V(d);for(auto&A:{&T,&O,&U,&V})for(auto&z:A->a)in>>z;require((bool)in,"complete local block");double before=double(clock())/CLOCKS_PER_SEC;auto K=bpower(T,O,29,-1);require(K.sg==-1,"final odd power sign");Mat P30=mul(K.p,T),T2=mul(T,T);Z dn=trprod(P30,T2),dh=32*trprod(P30,O);Z same=trprod(P30,U),adj=trprod(K.p,V),disj=trprod(K.r,O),db=32*(same-adj+disj);N+=dn;H+=dh;B2+=db;auto cp=std::filesystem::path(argv[3])/("checkpoint_"+std::to_string(k)+".json");require(!std::filesystem::exists(cp),"checkpoint already exists");std::ofstream out(cp);out<<"{\n  \"block_index\": "<<k<<",\n  \"charge\": "<<q<<",\n  \"side\": "<<d<<",\n  \"norm_contribution\": \""<<dn<<"\",\n  \"H_contribution\": \""<<dh<<"\",\n  \"B2_contribution\": \""<<db<<"\",\n  \"same_bond\": \""<<same<<"\",\n  \"adjacent_symmetric\": \""<<adj<<"\",\n  \"alternating_disjoint\": \""<<disj<<"\",\n  \"P29_max_bits\": "<<bits(K.p)<<",\n  \"R29_max_bits\": "<<bits(K.r)<<",\n  \"cpu_seconds_cumulative\": "<<double(clock())/CLOCKS_PER_SEC<<"\n}\n";out.close();require((bool)out,"checkpoint write");std::cerr<<"block="<<q<<" side="<<d<<" cpu_delta="<<double(clock())/CLOCKS_PER_SEC-before<<" cpu_total="<<double(clock())/CLOCKS_PER_SEC<<"\n";}std::string extra;require(!(in>>extra),"trailing block input");require(N==wantN&&H==wantH,"mandatory exact N0_32/H0_32 agreement");require(B2>=0&&B2<=N*2304,"physical B2 interval");std::cout<<"N0_32="<<N<<"\nH0_32="<<H<<"\nB2_32="<<B2<<"\nB2_NORMALIZING_B_SQUARED=2304\nEXACT_N0_H0_AGREEMENT=PASS\nL32_B2_ONLY_PASS\n";rusage u;getrusage(RUSAGE_SELF,&u);std::cerr<<"FINAL cpu="<<double(clock())/CLOCKS_PER_SEC<<" rss_kib="<<u.ru_maxrss<<" matrix_multiplications="<<muls<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAILED "<<e.what()<<" cpu="<<double(clock())/CLOCKS_PER_SEC<<"\n";return 2;}}
